function getFilterExcludedPullRequests(excludeLabels) {
  return (pullRequest) => {
    const labels = pullRequest.labels.nodes;
    if (labels.some((label) => excludeLabels.includes(label.name))) {
      return false;
    }
    return true;
  };
}
function getFilterIncludedPullRequests(includeLabels) {
  return (pullRequest) => {
    const labels = pullRequest.labels.nodes;
    if (includeLabels.length === 0 || labels.some((label) => includeLabels.includes(label.name))) {
      return true;
    }
    return false;
  };
}
function categorizePullRequests(pullRequests, config) {
  const excludeLabels = config?.["exclude-labels"] ?? [];
  const includeLabels = config?.["include-labels"] ?? [];
  const categories = Array.isArray(config?.categories) ? config.categories : [];
  const allCategoryLabels = new Set(categories.flatMap((category) => category.labels || []));
  const uncategorizedPullRequests = [];
  const categorizedPullRequests = [...categories].map((category) => ({
    ...category,
    pullRequests: []
  }));
  const uncategorizedCategoryIndex = categories.findIndex((category) => (category.labels?.length ?? 0) === 0);
  const filterUncategorizedPullRequests = (pullRequest) => {
    const labels = pullRequest.labels.nodes;
    if (labels.length === 0 || !labels.some((label) => allCategoryLabels.has(label.name))) {
      if (uncategorizedCategoryIndex === -1) {
        uncategorizedPullRequests.push(pullRequest);
      } else {
        categorizedPullRequests[uncategorizedCategoryIndex].pullRequests.push(pullRequest);
      }
      return false;
    }
    return true;
  };
  const filteredPullRequests = pullRequests.filter(getFilterExcludedPullRequests(excludeLabels)).filter(getFilterIncludedPullRequests(includeLabels)).filter((pullRequest) => filterUncategorizedPullRequests(pullRequest));
  for (const category of categorizedPullRequests) {
    for (const pullRequest of filteredPullRequests) {
      const labels = pullRequest.labels.nodes;
      if (labels.some((label) => (category.labels || []).includes(label.name))) {
        category.pullRequests.push(pullRequest);
      }
    }
  }
  return {
    uncategorized: uncategorizedPullRequests,
    categories: categorizedPullRequests
  };
}

// src/sponsor-html-checker.ts
async function checkSponsorPageExists(login) {
  const sponsorUrl = `https://github.com/sponsors/${login}`;
  try {
    const response = await fetch(sponsorUrl, {
      method: "HEAD",
      headers: {
        "User-Agent": "actionutils-gh-release-notes"
      },
      redirect: "manual"
    });
    if (response.status === 200) {
      logVerbose(`[SponsorHTML] Found sponsor page for ${login}`);
      return { sponsorUrl, hasError: false };
    }
    if (response.status >= 300 && response.status < 400) {
      logVerbose(`[SponsorHTML] No sponsor page for ${login} (redirected)`);
      return { hasError: false };
    }
    if (response.status === 404) {
      logVerbose(`[SponsorHTML] No sponsor page for ${login}`);
      return { hasError: false };
    }
    if (response.status === 429 || response.status >= 400 && response.status < 500) {
      logWarning(`[SponsorHTML] Got ${response.status} checking sponsor page for ${login}. ` + `This may indicate rate limiting or access restrictions. Skipping sponsor check.`);
      return { hasError: true };
    }
    logVerbose(`[SponsorHTML] Unexpected status ${response.status} for ${login}, assuming no sponsor page`);
    return { hasError: false };
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : String(error);
    logWarning(`[SponsorHTML] Failed to check sponsor page for ${login}: ${errorMessage}. ` + `Continuing without sponsor information.`);
    return { hasError: true };
  }
}
async function processBatch(batch, sponsorResults, errorTracker) {
  const promises = batch.map(async (login) => {
    const result = await checkSponsorPageExists(login);
    sponsorResults.set(login, result.sponsorUrl);
    return { login, ...result };
  });
  const results = await Promise.all(promises);
  let batchSuccessCount = 0;
  for (const result of results) {
    if (result.sponsorUrl) {
      batchSuccessCount++;
    } else if (result.hasError) {
      errorTracker.count++;
      if (errorTracker.count > 5) {
        errorTracker.shouldStop = true;
        logWarning(`[SponsorHTML] Too many errors checking sponsor pages. ` + `Stopping sponsor enrichment to avoid rate limits.`);
      }
    }
  }
  return { successCount: batchSuccessCount };
}
async function enrichWithHtmlSponsorData(pullRequests, maxConcurrency = 5) {
  logVerbose(`[SponsorHTML] Checking sponsor pages for ${pullRequests.length} PRs (max ${maxConcurrency} parallel)`);
  const uniqueAuthors = new Map;
  for (const pr of pullRequests) {
    const login = pr.author.login;
    if (pr.author.type === "User") {
      if (!uniqueAuthors.has(login)) {
        uniqueAuthors.set(login, new Set);
      }
      uniqueAuthors.get(login).add(pr.number);
    }
  }
  const authorsList = Array.from(uniqueAuthors.keys());
  logVerbose(`[SponsorHTML] Found ${authorsList.length} unique authors to check`);
  const sponsorResults = new Map;
  let totalSuccessCount = 0;
  const errorTracker = {
    count: 0,
    shouldStop: false
  };
  for (let i2 = 0;i2 < authorsList.length; i2 += maxConcurrency) {
    if (errorTracker.shouldStop) {
      for (let j = i2;j < authorsList.length; j++) {
        sponsorResults.set(authorsList[j], undefined);
      }
      break;
    }
    const batch = authorsList.slice(i2, i2 + maxConcurrency);
    logVerbose(`[SponsorHTML] Processing batch ${Math.floor(i2 / maxConcurrency) + 1}/${Math.ceil(authorsList.length / maxConcurrency)} (${batch.length} authors)`);
    const { successCount } = await processBatch(batch, sponsorResults, errorTracker);
    totalSuccessCount += successCount;
  }
  logVerbose(`[SponsorHTML] Found ${totalSuccessCount} sponsors out of ${authorsList.length} authors checked`);
  if (errorTracker.count > 5) {
    logVerbose(`[SponsorHTML] Returning original data due to errors`);
    return pullRequests;
  }
  return pullRequests.map((pr) => {
    const login = pr.author.login;
    if (pr.author.type !== "User") {
      return pr;
    }
    const sponsorUrl = sponsorResults.get(login);
    if (sponsorUrl) {
      return {
        ...pr,
        author: {
          ...pr.author,
          sponsorsListing: { url: sponsorUrl }
        }
      };
    }
    return pr;
  });
}

